with source_rows(domain_key,slug,canonical_name,website_url) as (values ('rwth-aachen.de','rwth-aachen-university','RWTH Aachen University','https://www.rwth-aachen.de/'),('uni-bonn.de','university-of-bonn','University of Bonn','https://www.uni-bonn.de/'),('fu-berlin.de','freie-universitaet-berlin','Freie Universität Berlin','https://www.fu-berlin.de/'),('hu-berlin.de','humboldt-universitaet-zu-berlin','Humboldt-Universität zu Berlin','https://www.hu-berlin.de/'),('tu.berlin','technische-universitaet-berlin','Technische Universität Berlin','https://www.tu.berlin/'),('tu-dresden.de','technische-universitaet-dresden','Technische Universität Dresden','https://tu-dresden.de/'),('uni-hamburg.de','universitaet-hamburg','Universität Hamburg','https://www.uni-hamburg.de/'),('uni-heidelberg.de','heidelberg-university','Heidelberg University','https://www.uni-heidelberg.de/'),('kit.edu','karlsruhe-institute-of-technology','Karlsruhe Institute of Technology','https://www.kit.edu/'),('lmu.de','ludwig-maximilians-universitaet-munich','Ludwig-Maximilians-Universität München','https://www.lmu.de/'),('tum.de','technical-university-of-munich','Technical University of Munich','https://www.tum.de/'),('uni-tuebingen.de','university-of-tuebingen','University of Tübingen','https://uni-tuebingen.de/')) insert into catalog.institutions(id,country_code,canonical_name,institution_type,website_url,status,slug,institution_kind,ownership_type) select md5('de:official-domain:'||domain_key)::uuid,'DE',canonical_name,'university',website_url,'active',slug,'university',null from source_rows on conflict(country_code,slug) where slug is not null do update set canonical_name=excluded.canonical_name,institution_type=excluded.institution_type,website_url=excluded.website_url,status=excluded.status,institution_kind=excluded.institution_kind,ownership_type=null,updated_at=now(); with source_rows(domain_key,slug,website_url) as (values ('rwth-aachen.de','rwth-aachen-university','https://www.rwth-aachen.de/'),('uni-bonn.de','university-of-bonn','https://www.uni-bonn.de/'),('fu-berlin.de','freie-universitaet-berlin','https://www.fu-berlin.de/'),('hu-berlin.de','humboldt-universitaet-zu-berlin','https://www.hu-berlin.de/'),('tu.berlin','technische-universitaet-berlin','https://www.tu.berlin/'),('tu-dresden.de','technische-universitaet-dresden','https://tu-dresden.de/'),('uni-hamburg.de','universitaet-hamburg','https://www.uni-hamburg.de/'),('uni-heidelberg.de','heidelberg-university','https://www.uni-heidelberg.de/'),('kit.edu','karlsruhe-institute-of-technology','https://www.kit.edu/'),('lmu.de','ludwig-maximilians-universitaet-munich','https://www.lmu.de/'),('tum.de','technical-university-of-munich','https://www.tum.de/'),('uni-tuebingen.de','university-of-tuebingen','https://uni-tuebingen.de/')) insert into catalog.institution_identifiers(institution_id,identifier_system,identifier_value,source_url) select i.id,'DE_HRK_VERIFIED_DOMAIN',s.domain_key,s.website_url from source_rows s join catalog.institutions i on i.country_code='DE' and i.slug=s.slug on conflict(identifier_system,identifier_value) do update set institution_id=excluded.institution_id,source_url=excluded.source_url; create or replace view public.institution_identity_de_v1 with(security_invoker=true) as select i.id institution_id,i.country_code,i.slug,i.canonical_name,official.identifier_value official_domain,official.source_url official_domain_source_url from catalog.institutions i join catalog.institution_identifiers official on official.institution_id=i.id and official.identifier_system='DE_HRK_VERIFIED_DOMAIN' where i.country_code='DE' and i.status<>'inactive' and i.slug is not null; revoke all on public.institution_identity_de_v1 from public,anon,authenticated; grant select on public.institution_identity_de_v1 to service_role; do $$ declare c int; begin select count(*) into c from public.institution_identity_de_v1; if c<>12 then raise exception 'Expected 12 DE identities, found %',c; end if; select count(*) into c from catalog.institutions where country_code='DE' and status<>'inactive' and (institution_kind is distinct from 'university' or ownership_type is not null or website_url !~ '^https://'); if c>0 then raise exception 'Invalid DE foundation rows %',c; end if; end $$;;
